import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Module 1 · The resident record","description":"","frontmatter":{},"headers":[],"relativePath":"modules/01-resident-record.md","filePath":"modules/01-resident-record.md","lastUpdated":1790431304000}'),n={name:"modules/01-resident-record.md"};function o(r,e,h,d,l,c){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="module-1-·-the-resident-record" tabindex="-1">Module 1 · The resident record <a class="header-anchor" href="#module-1-·-the-resident-record" aria-label="Permalink to &quot;Module 1 · The resident record&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contract</strong></td><td><code>ResidentRegistry.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>Town Hall</td></tr><tr><td><strong>Standard</strong></td><td>None — plain Solidity with role-based access control</td></tr><tr><td><strong>Stamp</strong></td><td>Module 1</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Trustville needs to know who lives there. Every later module depends on it: only residents can register products, issue certificates, harvest grain or claim the welcome grant.</p><p>The obvious approach is a list of names and addresses. It is also the wrong one, and understanding <em>why</em> is most of this module. A public blockchain is readable by everyone, for ever. Anything written to it is published — not &quot;shared with the university&quot;, not &quot;available on request&quot;, but published, permanently, to anyone who ever looks.</p><p>So the design question is not &quot;how do we store residents&quot; but <strong>how little can we store and still have the record be useful?</strong></p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>Store a <strong>hash</strong> of the credential document, never the document.</p><p>The student keeps their own file — a letter, an enrolment record, whatever the town accepts. The chain keeps a 32-byte fingerprint of it. Later, anyone holding the file can prove it is the one that was registered, by hashing it and comparing. Anyone <em>without</em> the file learns nothing at all.</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> register</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes32</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> credentialHash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">external</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ... stores the hash, the time, and who registered it</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>Hash function.</strong> A one-way function turning any input into a fixed-size output. Trustville uses <code>keccak256</code>, the one the EVM provides natively. Three properties matter:</p><ul><li><em>Deterministic</em> — the same input always gives the same output, so verification works.</li><li><em>One-way</em> — you cannot get the input back from the output, so publishing it is safe.</li><li><em>Avalanche</em> — changing one character changes roughly half the output bits, so &quot;close&quot; is meaningless. A document either matches or it does not.</li></ul><p><strong>Commitment.</strong> Publishing a hash is committing to a value without revealing it. You cannot change your mind later, because any other document produces a different hash. This one idea reappears in module 6 (sealed bids), module 7 (certificates) and module 13 (evidence).</p><p><strong>Role.</strong> A named permission. <code>REGISTRAR_ROLE</code> may register on someone&#39;s behalf and revoke; <code>DEFAULT_ADMIN_ROLE</code> may grant roles. Roles belong to <em>addresses</em>, and an address can be a contract — which is how module 3 prevents any human from minting money.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Resident</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> since;          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 0 = never registered</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> revokedAt;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 0 = active</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    bytes32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> credentialHash;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Three fields. No name, no email, no student number.</p><table tabindex="0"><thead><tr><th>Function</th><th>Who</th><th>What it does</th></tr></thead><tbody><tr><td><code>register(credentialHash)</code></td><td>anyone, while open</td><td>Registers the caller</td></tr><tr><td><code>registerFor(resident, hash)</code></td><td><code>REGISTRAR_ROLE</code></td><td>Registers somebody else — for a student who cannot transact yet</td></tr><tr><td><code>revoke(resident)</code></td><td><code>REGISTRAR_ROLE</code></td><td>Marks them revoked; the record stays</td></tr><tr><td><code>setOpenRegistration(bool)</code></td><td>admin</td><td>Open registration on or off</td></tr><tr><td><code>isResident(who)</code></td><td>anyone</td><td>The question every other contract asks</td></tr></tbody></table><p><strong>Revocation does not delete.</strong> <code>revokedAt</code> is a timestamp, and the original registration stays visible. A chain has no delete — <code>SELFDESTRUCT</code> is gone, and even overwriting storage leaves the history in every archive node. Designing as though deletion exists produces systems that quietly lie about their own guarantees.</p><p><strong>Open registration is a policy switch.</strong> <code>setOpenRegistration(false)</code> and only a registrar may add residents. For a course you want it open; for a town you probably do not.</p><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p><code>register</code> takes a hash, so <strong>the contract cannot check what it is a hash of</strong>. Registering <code>keccak256(&quot;&quot;)</code> or a hash of someone else&#39;s document both succeed.</p><p>That is not a flaw to fix in Solidity; it is the boundary of what the chain can know. The contract enforces <em>structure</em> — one registration per address, only a registrar may revoke. It cannot enforce <em>truth</em>. Truth needs somebody outside who checks documents, which is what <code>REGISTRAR_ROLE</code> represents.</p><p>Being able to say exactly where the guarantee stops is the skill this module is teaching.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li>Open Town Hall on the site and register.</li><li>Find the transaction on the explorer, and in it the <code>ResidentRegistered</code> event.</li><li>Read the <code>credentialHash</code> in the event data. This is public; everyone can see it.</li><li>Change one character of your credential text and hash it again — locally, no transaction. Compare. They share nothing.</li><li>Try to register a second time from the same address. It reverts with <code>AlreadyRegistered</code>.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ResidentRegistered(resident: 0x…, credentialHash: 0x…, registeredBy: 0x…)</span></span></code></pre></div><p>Storage now holds <code>since = &lt;block timestamp&gt;</code>, <code>revokedAt = 0</code>, and your hash. Roughly 65,000 gas — three storage slots written from zero, which is the most expensive thing the EVM does routinely. It is worth noticing now, because it is why later modules store hashes and counters rather than strings.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>Almost always, for this alone. A registry run by one university, used only by that university, gains nothing from being on a chain: the university could simply keep a table, and everyone already trusts it about its own students.</p><p>The case for a chain appears when <strong>the checker does not trust the keeper</strong>. An employer in another country, five years after you graduated, verifying that the record existed on a date and has not been edited since — without asking the university and without the university being able to quietly change it.</p><p>Be precise about that gap in your own designs, and honest when it is not there.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li>The chain does not know you are a real student. Someone decided that off-chain.</li><li>An address is not an identity. It is a public key, and people share, sell and lose them.</li><li>Correlation is a real risk: everything your address ever does is linked. Your registration plus your transaction history plus anything you post can identify you even though your name is nowhere on chain.</li></ul><p>That last point is worth sitting with. &quot;No names on chain&quot; is necessary, not sufficient.</p><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Storing the document to be helpful.</strong> Once, and it is public for ever.</li><li><strong>Assuming revocation removes it.</strong> It flags it.</li><li><strong>Hashing inconsistently.</strong> The UI hashes a specific string; verification must hash the same one or honest documents fail. Trailing newlines are the usual culprit.</li><li><strong>Treating <code>isResident</code> as identity.</strong> It says this address registered, nothing more.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Can somebody register on another person&#39;s behalf without the registrar role?</li><li>[ ] Can a revoked resident re-register and clear their history?</li><li>[ ] What happens if someone registers a hash of a document they do not hold?</li><li>[ ] Does anything in the registry reveal a person&#39;s identity on its own? With the rest of the chain? Combined with a public class list?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Add credential <em>expiry</em>, so a record goes stale rather than being revoked by hand. Then decide what other contracts should do about an expired resident — and notice that this is a policy question hiding in a technical one.</li><li>Let a resident update their credential hash, keeping the old one in history. What have you just made possible, and what have you made harder to audit?</li><li>Replace <code>REGISTRAR_ROLE</code> with a two-of-three multisig (module 11). Say what that costs in convenience and what it buys.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://docs.openzeppelin.com/contracts/5.x/access-control" target="_blank" rel="noreferrer">OpenZeppelin AccessControl</a></li><li><a href="https://ethereum.org/en/developers/docs/evm/opcodes/" target="_blank" rel="noreferrer">keccak256 and the Ethereum EVM</a></li><li>W3C Verifiable Credentials — the standards-track version of &quot;issuer signs, holder keeps, verifier checks&quot;, which module 7 follows more closely.</li></ul><p><strong>Next:</strong> <a href="./02-soulbound-passport">Module 2 · The soulbound Passport →</a></p>`,46)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
